use vstd::prelude::*;

verus! {

// Specification function to represent the value at position (i, j) in a 2D vector
spec fn matrix_get(input: Seq<Seq<i8>>, i: int, j: int) -> i8 {
    input[i][j]
}

// Specification function to represent a column extraction
spec fn spec_column(input: Seq<Seq<i8>>, j: int, n: int) -> Seq<i8>
    decreases n,
{
    if n == 0 {
        Seq::empty()
    } else {
        spec_column(input, j, n - 1).push(input[n - 1][j])
    }
}

// Specification function for the transposed matrix
spec fn spec_transpose(input: Seq<Seq<i8>>, m: int, n: int) -> Seq<Seq<i8>>
    decreases m,
{
    if m == 0 {
        Seq::empty()
    } else {
        spec_transpose(input, m - 1, n).push(spec_column(input, m - 1, n))
    }
}

fn get_column(input: &Vec<Vec<i8>>, j: usize, _m: usize, n: usize) -> (col: Vec<i8>)
    requires
        n == input.len(),
        forall|i: int| 0 <= i < n ==> #[trigger] input[i].len() > j,
    ensures
        col.len() == n,
        forall|i: int| 0 <= i < n ==> col[i] == input[i][j],
        col@ == spec_column(input@, j as int, n as int),
{
    // Preallocate a vector of length n to hold the column elements
    let mut col = Vec::with_capacity(n);
    let mut i: usize = 0;
    
    while i < n
        invariant
            i <= n,
            n == input.len(),
            forall|k: int| 0 <= k < n ==> #[trigger] input[k].len() > j,
            col.len() == i,
            forall|k: int| 0 <= k < i ==> col[k] == input[k][j],
        decreases n - i,
    {
        // For each row i, take the element at column j
        col.push(input[i][j]);
        i += 1;
    }
    
    assert(col@ == spec_column(input@, j as int, n as int)) by {
        assert(col.len() == n);
        assert forall|k: int| 0 <= k < n implies col[k] == input[k][j] by {
            assert(col[k] == input[k][j]);
        }
    }
    
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> (result: Vec<Vec<i8>>)
    requires
        n == input.len(),
        forall|i: int| 0 <= i < n ==> #[trigger] input[i].len() == m,
    ensures
        result.len() == m,
        forall|i: int| 0 <= i < m ==> #[trigger] result[i].len() == n,
        forall|i: int, j: int| 0 <= i < m && 0 <= j < n ==> 
            result[i][j] == input[j][i],
        result@ == spec_transpose(input@, m as int, n as int),
{
    let mut result = Vec::with_capacity(m); // m rows in the output matrix
    let mut j: usize = 0;
    
    // For each column index j in 0..m, extract column j as a row in the output
    while j < m
        invariant
            j <= m,
            n == input.len(),
            forall|i: int| 0 <= i < n ==> #[trigger] input[i].len() == m,
            result.len() == j,
            forall|i: int| 0 <= i < j ==> #[trigger] result[i].len() == n,
            forall|i: int, k: int| 0 <= i < j && 0 <= k < n ==> 
                result[i][k] == input[k][i],
        decreases m - j,
    {
        let col = get_column(&input, j, m, n);
        result.push(col);
        j += 1;
    }
    
    assert(result@ == spec_transpose(input@, m as int, n as int)) by {
        assert(result.len() == m);
        assert forall|i: int| 0 <= i < m implies result[i].len() == n by {
            assert(result[i].len() == n);
        }
        assert forall|i: int, k: int| 0 <= i < m && 0 <= k < n implies 
            result[i][k] == input[k][i] by {
            assert(result[i][k] == input[k][i]);
        }
    }
    
    result
}

}

